def parse_inline_math(inline: 'InlineParser', m: Match[str], state:
    'InlineState') ->int:
    text = m.group("math_text")
    state.append_token({"type": "inline_math", "raw": text})
    return m.end()


def render_inline_math(renderer: 'BaseRenderer', text: str) ->str:
    return '<span class="math">$' + text + '$</span>'


def math(md: 'Markdown') ->None:
    md.block_rules.insert(0, 'block_math')
    md.inline_rules.append('inline_math')
    md.register_plugin('block_math', parse_block_math, render_block_math)
    md.register_plugin('inline_math', parse_inline_math, render_inline_math)
